In MQL5, you can calculate a stop loss that represents 1% of your trading balance by following these steps:

## Method 1: Calculate Stop Loss Distance Based on Risk Amount

```mql5
//+------------------------------------------------------------------+
//| Calculate stop loss distance based on 1% risk                   |
//+------------------------------------------------------------------+
double CalculateStopLoss(string symbol, ENUM_ORDER_TYPE orderType, double lotSize, double riskPercent = 1.0)
{
    // Get account balance
    double balance = AccountInfoDouble(ACCOUNT_BALANCE);

    // Calculate risk amount (1% of balance)
    double riskAmount = balance * (riskPercent / 100.0);

    // Get symbol info
    double tickSize = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_SIZE);
    double tickValue = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_VALUE);
    double point = SymbolInfoDouble(symbol, SYMBOL_POINT);

    // Calculate stop loss distance in points
    double stopLossPoints = (riskAmount / (lotSize * tickValue)) * tickSize / point;

    // Get current price
    double currentPrice;
    if(orderType == ORDER_TYPE_BUY)
        currentPrice = SymbolInfoDouble(symbol, SYMBOL_ASK);
    else
        currentPrice = SymbolInfoDouble(symbol, SYMBOL_BID);

    // Calculate stop loss price
    double stopLossPrice;
    if(orderType == ORDER_TYPE_BUY)
        stopLossPrice = currentPrice - (stopLossPoints * point);
    else
        stopLossPrice = currentPrice + (stopLossPoints * point);

    // Normalize the price
    int digits = (int)SymbolInfoInteger(symbol, SYMBOL_DIGITS);
    stopLossPrice = NormalizeDouble(stopLossPrice, digits);

    return stopLossPrice;
}
```

## Method 2: Complete Trading Function with 1% Risk

```mql5
//+------------------------------------------------------------------+
//| Place order with 1% risk stop loss                              |
//+------------------------------------------------------------------+
bool PlaceOrderWithRisk(string symbol, ENUM_ORDER_TYPE orderType, double lotSize, double riskPercent = 1.0)
{
    MqlTradeRequest request = {};
    MqlTradeResult result = {};

    // Calculate stop loss
    double stopLoss = CalculateStopLoss(symbol, orderType, lotSize, riskPercent);

    // Get current prices
    double price;
    if(orderType == ORDER_TYPE_BUY)
        price = SymbolInfoDouble(symbol, SYMBOL_ASK);
    else
        price = SymbolInfoDouble(symbol, SYMBOL_BID);

    // Prepare the request
    request.action = TRADE_ACTION_DEAL;
    request.symbol = symbol;
    request.volume = lotSize;
    request.type = orderType;
    request.price = price;
    request.sl = stopLoss;
    request.tp = 0; // Set take profit if needed
    request.deviation = 3;
    request.magic = 12345; // Your magic number
    request.comment = "1% Risk Order";

    // Send the order
    bool success = OrderSend(request, result);

    if(success)
    {
        Print("Order placed successfully. Ticket: ", result.order);
        Print("Stop Loss set at: ", stopLoss);
        Print("Risk amount: ", AccountInfoDouble(ACCOUNT_BALANCE) * (riskPercent/100.0));
        return true;
    }
    else
    {
        Print("Order failed. Error: ", GetLastError());
        Print("Result code: ", result.retcode);
        return false;
    }
}
```

## Method 3: Calculate Lot Size Based on Fixed Stop Loss Distance

If you prefer to set a fixed stop loss distance and calculate the lot size for 1% risk:

```mql5
//+------------------------------------------------------------------+
//| Calculate lot size for 1% risk with fixed SL distance           |
//+------------------------------------------------------------------+
double CalculateLotSize(string symbol, double stopLossPoints, double riskPercent = 1.0)
{
    // Get account balance
    double balance = AccountInfoDouble(ACCOUNT_BALANCE);

    // Calculate risk amount
    double riskAmount = balance * (riskPercent / 100.0);

    // Get symbol info
    double tickSize = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_SIZE);
    double tickValue = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_VALUE);
    double point = SymbolInfoDouble(symbol, SYMBOL_POINT);

    // Calculate lot size
    double lotSize = riskAmount / (stopLossPoints * point * tickValue / tickSize);

    // Get min/max lot size
    double minLot = SymbolInfoDouble(symbol, SYMBOL_VOLUME_MIN);
    double maxLot = SymbolInfoDouble(symbol, SYMBOL_VOLUME_MAX);
    double lotStep = SymbolInfoDouble(symbol, SYMBOL_VOLUME_STEP);

    // Normalize lot size
    lotSize = MathMax(minLot, MathMin(maxLot, lotSize));
    lotSize = NormalizeDouble(lotSize / lotStep, 0) * lotStep;

    return lotSize;
}
```

## Usage Example:

```mql5
//+------------------------------------------------------------------+
//| Expert initialization function                                   |
//+------------------------------------------------------------------+
int OnInit()
{
    // Example usage
    string symbol = _Symbol;
    ENUM_ORDER_TYPE orderType = ORDER_TYPE_BUY;
    double lotSize = 0.1;

    // Method 1: Calculate SL for fixed lot size
    double stopLoss = CalculateStopLoss(symbol, orderType, lotSize, 1.0);
    Print("Stop Loss Price: ", stopLoss);

    // Method 2: Place order with 1% risk
    PlaceOrderWithRisk(symbol, orderType, lotSize, 1.0);

    // Method 3: Calculate lot size for fixed SL distance (50 points)
    double calculatedLotSize = CalculateLotSize(symbol, 50, 1.0);
    Print("Calculated Lot Size for 1% risk: ", calculatedLotSize);

    return(INIT_SUCCEEDED);
}
```

## Key Points:

1. **Risk Calculation**: `riskAmount = balance * 0.01` (1% of balance)
2. **Price Normalization**: Always normalize prices using `NormalizeDouble()`
3. **Symbol Properties**: Use `SymbolInfo` functions to get tick size, tick value, and other symbol-specific data
4. **Lot Size Validation**: Ensure lot sizes comply with broker's minimum/maximum requirements
5. **Error Handling**: Always check for errors when placing orders

This approach ensures that regardless of the trade outcome, you'll never lose more than 1% of your account balance on a single trade when the stop loss is hit.

